def start_fake(folder):
    shutil.rmtree(folder, ignore_errors=True)
    os.makedirs(folder)
    err = open(os.path.join(folder, "fake.stderr"), "w")
    child = subprocess.Popen([sys.executable, FAKE, "--dir", folder], env=child_env(),
